INSERT INTO dump_descriptions (base_key, description) VALUES ('antilag-0.1.0-alpha.5-r9', 'Client-side movement correction mod that protects eligible walking, falling, and grapple movement from host corrections, then returns to stock correction until a genuine host acknowledgement after unsupported states.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('mk series', 'Adds six Mk custom-difficulty presets, roughly Hazard 3 through Hazard 9+, with enemy-pool and cap changes plus mission-specific resupply or nitra-pressure variants.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('u40', 'Adds five Update 40 custom-difficulty presets for Hazards 6–9+, changing enemy waves, resistances, caps, and resupply settings; the author notes timed surges and altered enemy rosters.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('v0.21', 'Adds Chinese custom-difficulty presets for tiers 1–9 plus a Clear 6 challenge; the author notes describe enemy roster, wave timing, cap, resistance, and challenge-objective changes.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
